.shop{background:radial-gradient(ellipse at 10% 0%,#65171c2a,transparent 45%),#0d111a;border-block:1px solid #ffffff0b}
.cs-grid{display:grid;grid-template-columns:1fr 340px;gap:30px;align-items:start}
.cs-st{display:flex;align-items:center;gap:10px;font-size:16px;margin:0 0 14px}.cs-st b{background:var(--gold);color:#14100a;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-size:13px}
.cs-packs{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px;margin-bottom:20px}
.cs-pack{background:var(--panel2);border:2px solid var(--line);border-radius:10px;padding:14px;text-align:left;color:var(--white);cursor:pointer}
.cs-pack .n{display:block;font-size:22px;font-weight:900}.cs-pack small{display:block;color:var(--muted);margin-top:2px;font-size:11px}.cs-pack[aria-pressed=true]{border-color:var(--gold)}
.cs-two{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.cs-note{font-size:11px;color:var(--muted);margin-top:8px;line-height:1.6}
.cs-side{background:#171e2cee;border:1px solid var(--line);border-radius:14px;padding:22px;position:sticky;top:96px}
.cs-side h3{margin:0 0 14px;font-size:18px}.cs-side dl{margin:0 0 18px;display:grid;grid-template-columns:auto 1fr;gap:8px 14px;font-size:13px}
.cs-side dt{color:var(--muted)}.cs-side dd{margin:0;text-align:right;word-break:break-word}.cs-big{font-size:20px;font-weight:900;color:var(--gold)}
.cs-ob{border-top:1px solid var(--line);margin-top:14px;padding-top:12px;font-size:12px;line-height:1.7}.cs-ob p{margin:0 0 10px}
.form-grid .form-card:last-child{grid-column:1/-1}
@media(max-width:920px){.cs-grid{grid-template-columns:1fr}.cs-side{position:static}}
@media(max-width:600px){.cs-two{grid-template-columns:1fr}.form-grid .form-card:last-child{grid-column:auto}}

.cs-srv{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:22px}.cs-lead{font-size:14px;line-height:1.7;color:var(--white)}.cs-lead b{color:var(--gold)}
.live{padding:48px 0 8px;text-align:center}
.lv-on{display:inline-flex;align-items:center;gap:10px;letter-spacing:.3em;font-weight:800;font-size:14px}
.lv-dot{width:12px;height:12px;border-radius:50%;background:#46e08a;box-shadow:0 0 12px #46e08a}
.lv-num{font-size:clamp(56px,14vw,96px);font-weight:900;color:var(--gold);line-height:1.05;margin:6px 0}
