.lv-cd{margin-top:34px}.cd{display:flex;justify-content:center;gap:10px;margin-top:14px}
.cd div{background:var(--panel2);border:1px solid var(--line);border-radius:12px;min-width:68px;padding:14px 8px}
.cd b{display:block;font-size:clamp(24px,7vw,38px);font-weight:900}.cd small{color:var(--muted);font-size:10px;letter-spacing:.12em;text-transform:uppercase}
.news-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:16px}
.news-card{background:#f7f8fb;color:#12151e;border-radius:16px;padding:20px;display:flex;flex-direction:column;gap:8px}
.news-card small{color:#667}.news-card h3{margin:0;font-size:18px;text-transform:uppercase}.news-card p{margin:0;font-size:13px;line-height:1.7;white-space:pre-wrap}
.news-card button{align-self:flex-start;background:none;border:1px solid #c33;color:#c33;border-radius:8px;padding:6px 10px;font-size:11px;cursor:pointer}
.adm{margin-top:28px}

.news-card img{width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:10px}
.news-k{align-self:flex-start;background:var(--red);color:#fff;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;padding:4px 9px;border-radius:99px}
.clamp{display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;overflow:hidden}
.news-card .more{border-color:#667;color:#334}
.sheet{position:fixed;inset:0;z-index:90;background:var(--bg);overflow:auto}.sheet[hidden]{display:none}
.sheet-bar{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;align-items:center;padding:14px 5%;padding-top:calc(14px + env(safe-area-inset-top,0px));background:#090b12;border-bottom:1px solid var(--line)}
.sheet-bar button{background:var(--red);color:#fff;border:0;border-radius:9px;padding:10px 16px;font-weight:800;font-size:13px;cursor:pointer}
.sheet-body{max-width:980px;margin:0 auto;padding:24px 5% 70px}.panel{display:none}.panel.open{display:block}
.panel>.form-card{max-width:640px;margin:0 auto}.panel .shop{background:none;border:0}
