.links.open{display:flex!important}.links a{font-size:14px;text-align:center;padding:14px 0;letter-spacing:.08em}
.nav-actions .btn{display:none}

section[id]{scroll-margin-top:84px}img,video,svg{max-width:100%}img{height:auto}
