[hidden]{display:none!important}

.lv-stats{display:flex;flex-wrap:wrap;justify-content:center;gap:18px}
.lv-stat{flex:1 1 260px;max-width:420px;background:linear-gradient(160deg,#171e2c,#0d111a);border:1px solid var(--line);border-radius:18px;padding:22px 18px}
.lv-num{text-shadow:0 0 18px #ffbd4222}
.lv-join{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;margin-top:22px}

.lv-stat .lv-num{font-size:clamp(44px,12vw,72px)}

