<script>
const menu=document.getElementById('menuBtn'),nav=document.getElementById('navlinks');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');menu.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}));document.getElementById('year').textContent=new Date().getFullYear();
async function sendForm(formId,endpoint,statusId){const form=document.getElementById(formId),status=document.getElementById(statusId);form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;button.textContent='SENDING…';status.textContent='Please wait while we submit your request.';try{await new Promise(r=>setTimeout(r,500));status.textContent='Preview mode: this form is not connected to email here. It will send once deployed with server.py.';form.reset()}catch(err){status.textContent=err.message+' If this continues, contact the official support team.'}finally{button.disabled=false;button.textContent=endpoint.includes('topup')?'SEND TOP-UP ORDER':endpoint.includes('recovery')?'SEND RECOVERY REQUEST':endpoint.includes('partnership')?'SEND PARTNERSHIP ENQUIRY':'SEND MESSAGE'}})}

</script><script>(function(){
var RATE=2,MIN=100,MAX=500000,PRESETS=[500,1000,2500,5000,10000,25000],METHODS=["Bank transfer","PayPal","Crypto (USDT)","Mobile money","Other"];
var RATES={USD:1,EUR:.92,GBP:.79,NGN:1550,GHS:15,KES:129,ZAR:18,EGP:49,MAD:10,TZS:2650,UGX:3700,XOF:610,INR:84,PKR:280,BDT:120,IDR:15800,PHP:57,VND:25000,THB:35,MYR:4.5,TRY:34,RUB:95,UAH:41,PLN:4,BRL:5.5,MXN:19,ARS:1000,CLP:940,COP:4100,PEN:3.8,CAD:1.37,AUD:1.5,NZD:1.65,JPY:150,KRW:1350,CNY:7.2,AED:3.67,SAR:3.75,SGD:1.33,CHF:.88,SEK:10.5,NOK:10.8,DKK:6.9,CZK:23,HUF:365,ILS:3.7,KZT:480};
var REGION={NG:"NGN",GH:"GHS",KE:"KES",ZA:"ZAR",EG:"EGP",MA:"MAD",TZ:"TZS",UG:"UGX",SN:"XOF",CI:"XOF",IN:"INR",PK:"PKR",BD:"BDT",ID:"IDR",PH:"PHP",VN:"VND",TH:"THB",MY:"MYR",TR:"TRY",RU:"RUB",UA:"UAH",PL:"PLN",BR:"BRL",MX:"MXN",AR:"ARS",CL:"CLP",CO:"COP",PE:"PEN",CA:"CAD",AU:"AUD",NZ:"NZD",JP:"JPY",KR:"KRW",CN:"CNY",AE:"AED",SA:"SAR",SG:"SGD",CH:"CHF",SE:"SEK",NO:"NOK",DK:"DKK",CZ:"CZK",HU:"HUF",IL:"ILS",KZ:"KZT",GB:"GBP",DE:"EUR",FR:"EUR",ES:"EUR",IT:"EUR",NL:"EUR",PT:"EUR",IE:"EUR"};
function $(i){return document.getElementById(i)}
function newId(){var a="ABCDEFGHJKMNPQRSTUVWXYZ23456789",r="",d=new Date();for(var i=0;i<6;i++)r+=a[Math.floor(Math.random()*a.length)];return"NR-"+String(d.getMonth()+1).padStart(2,"0")+String(d.getDate()).padStart(2,"0")+"-"+r}
var OWNER_EMAIL="naija.republic.rp@gmail.com";
var pending=null,cur="USD",coins=500,server="",box=$("csPacks");
var nm=(function(){try{var dn=new Intl.DisplayNames(undefined,{type:"currency"});return function(c){return c+" – "+dn.of(c)}}catch(e){return function(c){return c}}})();
function naira(n){return "₦"+n.toLocaleString("en-US")}
function show(ngn){if(cur==="NGN")return naira(ngn);try{var v=ngn/RATES.NGN*RATES[cur],big=v>=100;return new Intl.NumberFormat(undefined,{style:"currency",currency:cur,maximumFractionDigits:big?0:2,minimumFractionDigits:big?0:2}).format(v)}catch(e){return cur}}
Object.keys(RATES).forEach(function(c){var o=document.createElement("option");o.value=c;o.textContent=nm(c);$("csCur").appendChild(o)});
try{var rg=(navigator.language||"en-US").split("-")[1];if(rg&&REGION[rg.toUpperCase()])cur=REGION[rg.toUpperCase()]}catch(e){}
$("csCur").value=cur;
var f=document.createElement("option");f.value="";f.textContent="Select…";$("csPm").appendChild(f);
METHODS.forEach(function(x){var o=document.createElement("option");o.value=x;o.textContent=x;$("csPm").appendChild(o)});
$("csSRate").textContent=naira(RATE)+" per coin";
$("csHint").textContent="Minimum "+MIN.toLocaleString()+" coins. Rate: "+naira(RATE)+" per coin.";
PRESETS.forEach(function(n){var b=document.createElement("button");b.type="button";b.className="cs-pack";b.dataset.c=n;b.innerHTML="<span class='n'></span><small></small>";b.querySelector(".n").textContent=n.toLocaleString();b.onclick=function(){coins=n;$("csAmt").value=n;update()};box.appendChild(b)});
function update(){var ok=coins>=MIN&&coins<=MAX,ngn=coins*RATE;
box.querySelectorAll(".cs-pack").forEach(function(b){var n=+b.dataset.c;b.setAttribute("aria-pressed",n===coins?"true":"false");b.querySelector("small").textContent=show(n*RATE)});
$("csSCoins").textContent=ok?coins.toLocaleString():"–";$("csTotal").textContent=ok?naira(ngn):"–";
$("csEstT").textContent="In "+cur;$("csSEst").textContent=ok?show(ngn):"–";$("csEstT").style.display=$("csSEst").style.display=cur==="NGN"?"none":"";
$("csSPlayer").textContent=$("csPid").value.trim()||"–";$("csSPay").textContent=$("csPm").value||"–";$("csSServer").textContent=server||"–";$("csOrder").hidden=true}
$("csAmt").addEventListener("input",function(){var v=Math.floor(Number(this.value));coins=isFinite(v)?v:0;update()});
document.querySelectorAll("#csServers .cs-pack").forEach(function(b){b.onclick=function(){server=b.dataset.s;document.querySelectorAll("#csServers .cs-pack").forEach(function(x){x.setAttribute("aria-pressed",x===b?"true":"false");x.querySelector("small").textContent=x===b?"Selected":"Tap to select"});update()}});
$("csCur").onchange=function(){cur=this.value;update()};$("csPm").onchange=update;$("csPid").addEventListener("input",update);update();
$("csPay").onclick=function(){var m=$("csMsg");m.textContent="";$("csOrder").hidden=true;
var pid=$("csPid").value.trim(),pm=$("csPm").value,mail=$("csMail").value.trim();
if(!server){m.textContent="Choose Server 01 or Server 02.";return}
if(!(coins>=MIN&&coins<=MAX)){m.textContent="Enter an amount between "+MIN.toLocaleString()+" and "+MAX.toLocaleString()+" coins.";return}
if(!pid){m.textContent="Enter your character name.";return}
if(!/^\S+@\S+\.\S+$/.test(mail)){m.textContent="Enter a valid email so we can reply to you.";return}
if(!pm){m.textContent="Choose a payment method.";return}
var region=$("csCur").options[$("csCur").selectedIndex].text,total=naira(coins*RATE);
var oid=newId(),n=coins.toLocaleString();var su="Order "+oid+": "+n+" in-game coins ("+server+")";
var body="NAIJA REPUBLIC RP - COIN ORDER\n\nOrder ID: "+oid+"\nDate: "+new Date().toLocaleString()+"\n\nItem: "+n+" in-game coins (Republic coins)\nQuantity: "+n+"\nRate: "+naira(RATE)+" per coin\nTotal: "+total+"\nEstimate in my currency: "+show(coins*RATE)+"\n\nServer: "+server+"\nCharacter name: "+pid+"\nRegion: "+region+"\nPayment method: "+pm+"\nEmail: "+mail+"\n";
$("csBCoins").textContent=coins.toLocaleString();$("csBServer").textContent=server;$("csBName").textContent=pid;$("csBTotal").textContent=total;$("csBId").textContent=oid;
$("csGmail").href="https://mail.google.com/mail/?view=cm&fs=1&to="+encodeURIComponent(OWNER_EMAIL)+"&su="+encodeURIComponent(su)+"&body="+encodeURIComponent(body);
$("csMailto").href="mailto:"+OWNER_EMAIL+"?subject="+encodeURIComponent(su)+"&body="+encodeURIComponent(body);
pending={id:oid,server:server,coins:coins,player:pid,email:mail,method:pm,region:region,estimate:show(coins*RATE)};$("csSend").hidden=false;$("csSend").disabled=false;$("csSendMsg").textContent="";$("csDone").hidden=true;$("csFallback").hidden=true;
$("csOrder").hidden=false;$("csOrder").scrollIntoView({behavior:"smooth",block:"nearest"})};
$("csSend").onclick=function(){if(!pending)return;var b=$("csSend"),m=$("csSendMsg"),sent=pending;b.disabled=true;m.textContent="Sending your order…";
 fetch("/api/order",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(sent)})
 .then(function(r){return r.json().then(function(j){return{s:r.status,j:j}},function(){return{s:r.status,j:null}})})
 .then(function(x){
  if(x.j&&x.j.ok){m.textContent="";b.hidden=true;$("csFallback").hidden=true;$("csDone").hidden=false;$("csDone").textContent="Order "+x.j.id+" received. A confirmation was sent to "+sent.email+". We will reply with how to pay.";return}
  if(x.j&&x.j.error&&(x.s===400||x.s===429)){m.textContent=x.j.error;b.disabled=false;return}
  throw new Error("fallback")})
 .catch(function(){m.textContent="We could not send it automatically. Please send it with Gmail below.";$("csFallback").hidden=false;b.disabled=false})};
$("csUseGmail").onclick=function(e){e.preventDefault();$("csFallback").hidden=false};
})();
</script><script>(function(){
var OWNER="naija.republic.rp@gmail.com";
var DEFS={
 recoveryForm:{ep:"/api/recovery",status:"recStatus",subject:"Account recovery request",fields:[["character","Character name"],["server","Server"],["device","Device model"],["location","Country and city when registered"],["email","Email linked to the account"],["telegram","Telegram linked to the account"],["contact","Contact details"],["details","Issue description"]]},
 partnerForm:{ep:"/api/partnership",status:"partnerStatus",subject:"Partnership enquiry",fields:[["name","Name / organisation"],["email","Contact email"],["type","Partnership type"],["details","Proposal"]]},
 contactForm:{ep:"/api/contact",status:"contactStatus",subject:"Support message",fields:[["name","Name"],["email","Email"],["subject","Category"],["details","Message"]]}
};
Object.keys(DEFS).forEach(function(id){
 var d=DEFS[id],form=document.getElementById(id),st=document.getElementById(d.status);
 form.addEventListener("submit",function(e){
  e.preventDefault();
  var data=Object.fromEntries(new FormData(form)),btn=form.querySelector('button[type="submit"]');
  var subj="NAIJA REPUBLIC RP: "+d.subject+(data.subject?" ("+data.subject+")":"");
  var body=d.subject.toUpperCase()+"\n\n"+d.fields.map(function(f){return f[1]+": "+(data[f[0]]||"Not provided")}).join("\n\n")+"\n";
  var g="https://mail.google.com/mail/?view=cm&fs=1&to="+encodeURIComponent(OWNER)+"&su="+encodeURIComponent(subj)+"&body="+encodeURIComponent(body);
  var m="mailto:"+OWNER+"?subject="+encodeURIComponent(subj)+"&body="+encodeURIComponent(body);
  btn.disabled=true;st.textContent="Sending…";
  fetch(d.ep,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)})
  .then(function(r){return r.json().then(function(j){return{s:r.status,j:j}},function(){return{s:r.status,j:null}})})
  .then(function(x){
   if(x.j&&x.j.message&&x.s===200){st.textContent=x.j.message;form.reset();return}
   if(x.j&&x.j.error&&x.s===400){st.textContent=x.j.error;return}
   throw new Error("fallback")})
  .catch(function(){
   st.textContent="We could not send it automatically. Press the button to send it with Gmail. ";
   var a=document.createElement("a");a.href=g;a.target="_blank";a.rel="noopener";a.className="btn";a.style.cssText="width:100%;margin-top:10px";a.textContent="Continue to Gmail →";
   var o=document.createElement("a");o.href=m;o.textContent="Use your default mail app";o.style.cssText="display:block;margin-top:10px;color:var(--gold);font-size:11px";
   st.appendChild(a);st.appendChild(o)})
  .then(function(){btn.disabled=false});
 });
 form.addEventListener("input",function(){st.textContent=""});
});
})();
