 window.NR_auth({mode:mode,name:$("aName").value,email:$("aMail").value,password:pw,confirm:$("aConf").value}).then(function(r){$("aPass").value=$("aConf").value="";window.NR_setMe(r.user)}).catch(function(x){msg.textContent=x.message}).then(function(){b.disabled=false})});
