if(window.NR_MUSIC_SRC)start(window.NR_MUSIC_SRC);else fetch("/music",{method:"HEAD"}).then(function(r){if(!r.ok||!/audio/.test(r.headers.get("content-type")||""))return;start("/music")}).catch(function(){});
function start(src){
 var au=new Audio(src);au.loop=true;au.volume=.4;au.preload="auto";
 var muted=false;try{muted=localStorage.getItem("nrMusic")==="off"}catch(e){}
 var b=document.createElement("button");b.type="button";b.setAttribute("aria-label","Music on or off");
 b.style.cssText="position:fixed;left:14px;bottom:calc(14px + env(safe-area-inset-bottom,0px));z-index:70;width:46px;height:46px;border-radius:50%;border:1px solid #ffffff33;background:#0d111ae6;color:#ffbd42;font-size:20px;cursor:pointer";
 function paint(){b.textContent=muted||au.paused?"\u{1F507}":"\u{1F50A}"}
 function play(){if(muted)return;au.play().then(paint).catch(function(){})}
 b.onclick=function(){muted=!muted;try{localStorage.setItem("nrMusic",muted?"off":"on")}catch(e){}if(muted)au.pause();else au.play().catch(function(){});paint()};
 document.body.appendChild(b);paint();play();
 ["pointerdown","touchstart","keydown","click"].forEach(function(ev){var f=function(){play();if(!au.paused)["pointerdown","touchstart","keydown","click"].forEach(function(x){document.removeEventListener(x,f,true)})};document.addEventListener(ev,f,true)});
}
})();
