function nr_music_b64(): string
{
    return <<<'NR_END_MUSIC'

NR_END_MUSIC;
}

// ------------------------------------------------------------------ dispatcher
header('X-Content-Type-Options: nosniff');

$method = strtoupper($_SERVER['REQUEST_METHOD'] ?? 'GET');
$path = rawurldecode((string) (parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH) ?: '/'));
if ($path !== '/') $path = rtrim($path, '/');
if (str_starts_with($path, '/api/')) header('Cache-Control: no-store');

set_exception_handler(function (Throwable $e) use ($path): void {
    error_log('NR error: ' . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine());
    if (!headers_sent()) http_response_code(500);
    if (str_starts_with($path, '/api/')) {
        header('Content-Type: application/json');
        echo json_encode(['error' => 'Something went wrong. Please try again.']);
    } else {
        echo 'Server error';
    }
});

if (in_array($method, ['POST', 'PUT', 'PATCH', 'DELETE'], true) && (int) ($_SERVER['CONTENT_LENGTH'] ?? 0) > MAX_BODY) {
    out_error('Request too large.', 413);
}

const ROUTES = [
    ['GET', '#^/$#', 'r_home'],
    ['GET', '#^/download$#', 'r_download'],
    ['GET', '#^/terms$#', 'r_terms'],
    ['GET', '#^/privacy$#', 'r_privacy'],
    ['GET', '#^/music$#', 'r_music'],
    ['GET', '#^/health$#', 'r_health'],
    ['GET', '#^/admin\.js$#', 'r_admin_js'],
    ['GET', '#^/api/me$#', 'r_me'],
    ['GET', '#^/api/site$#', 'r_site'],
    ['GET', '#^/api/admin/seats$#', 'r_admin_seats'],
    ['GET', '#^/api/admin/members$#', 'r_admin_members'],
    ['POST', '#^/api/auth$#', 'r_auth'],
    ['POST', '#^/api/logout$#', 'r_logout'],
    ['POST', '#^/api/visit$#', 'r_visit'],
    ['POST', '#^/api/order$#', 'r_order'],
    ['POST', '#^/api/topup$#', 'r_topup'],
    ['POST', '#^/api/recovery$#', 'r_recovery'],
    ['POST', '#^/api/partnership$#', 'r_partnership'],
    ['POST', '#^/api/contact$#', 'r_contact'],
    ['POST', '#^/api/admin/news$#', 'r_admin_news'],
    ['DELETE', '#^/api/admin/news/(\d+)$#', 'r_admin_news_delete'],
    ['POST', '#^/api/admin/launch$#', 'r_admin_launch'],
    ['POST', '#^/api/admin/community$#', 'r_admin_community'],
    ['POST', '#^/api/admin/seats/revoke$#', 'r_admin_seat_revoke'],
];

$pathMatched = false;
$lookup = $method === 'HEAD' ? 'GET' : $method;
foreach (ROUTES as [$m, $re, $fn]) {
    if (preg_match($re, $path, $mm)) {
        $pathMatched = true;
        if ($m === $lookup) { $fn($mm); }
    }
}
if ($pathMatched) {
    header('Allow: GET, POST, DELETE');
    if (str_starts_with($path, '/api/')) out_error('Method not allowed.', 405);
    http_response_code(405); exit('Method Not Allowed');
}
if (str_starts_with($path, '/api/')) out_error('Not found.', 404);
http_response_code(404);
echo 'Not Found';
